"""Depth-limited topological sort that reports cycles."""


def toposort(graph, max_depth=64):
    state = {}
    order = []

    def visit(node, depth):
        if depth > max_depth:
            raise RecursionError("graph deeper than %d" % max_depth)
        s = state.get(node)
        if s == "done":
            return
        if s == "open":
            raise ValueError("cycle through %r" % node)
        state[node] = "open"
        for nxt in graph.get(node, ()):
            visit(nxt, depth + 1)
        state[node] = "done"
        order.append(node)

    for node in graph:
        visit(node, 0)
    return order
